self.addEventListener('install', function(e){
  // cache.addAll() is all-or-nothing - one 404 in CORE would reject the WHOLE
  // install and silently leave the app with no offline support at all. The
  // Python build already fails loudly on a missing referenced image (see
  // copy_asset()), but this is the belt-and-braces case for anything that
  // slips past that (a CDN hiccup, a locally-edited CORE, etc.): cache every
  // entry independently and only complain - loudly, to the console, not
  // silently - about whichever ones actually failed.
  e.waitUntil(
    caches.open(CACHE).then(function(c){
      return Promise.allSettled(CORE.map(function(url){ return c.add(url); }));
    }).then(function(results){
      var failed = results.filter(function(r){ return r.status === 'rejected'; });
      if (failed.length){
        console.error('[drug-webapp sw] ' + failed.length + ' of ' + CORE.length +
          ' core asset(s) failed to precache - offline support is degraded:',
          failed.map(function(r){ return r.reason && r.reason.message; }));
      }
      return self.skipWaiting();
    })
  );
});
self.addEventListener('activate', function(e){
  e.waitUntil(caches.keys().then(function(keys){
    return Promise.all(keys.filter(function(k){ return k !== CACHE; }).map(function(k){ return caches.delete(k); }));
  }).then(function(){ return self.clients.claim(); }));
});
self.addEventListener('fetch', function(e){
  if (e.request.method !== 'GET') return;

  // 🔴 NAVIGATIONS ARE NETWORK-FIRST. This handler used to be cache-first for
  // EVERYTHING, index.html included - so the moment a build shipped, an
  // already-installed device kept serving the previous app out of its old
  // cache and the new feature simply did not exist for him. Prat hit exactly
  // that on 2026-08-17: the slide button was live and verified on the server,
  // and his own app showed "the same structure and also appear and nothing
  // else." The new service worker DOES install and claim, but only after the
  // old one has already answered that first navigation from cache, so the fix
  // needed two reloads and he had no way to know that.
  // Network-first here means a deploy is visible on the next load, and the
  // cached copy is still the offline fallback - the only thing it costs is one
  // network round-trip for the HTML when he is online.
  if (e.request.mode === 'navigate'){
    e.respondWith(
      fetch(e.request).then(function(resp){
        if (resp && resp.ok){
          var copy = resp.clone();
          caches.open(CACHE).then(function(c){ c.put('./index.html', copy); });
        }
        return resp;
      }).catch(function(){
        return caches.match('./index.html').then(function(c){
          return c || caches.match('./');
        });
      })
    );
    return;
  }

  e.respondWith(
    caches.match(e.request).then(function(cached){
      if (cached) return cached;
      return fetch(e.request).then(function(resp){
        // Cache the heavy on-demand assets after their first view so the app
        // still works on the train: the printable PDFs, and (since 2026-08-17)
        // the lecture decks + the free-text page text behind them. These are
        // deliberately NOT in CORE - 184 MB through cache.addAll() would
        // reject the whole install.
        var u = e.request.url;
        if (resp.ok && (u.indexOf('/pdfs/') !== -1 || u.indexOf('/slides/') !== -1)){
          var copy = resp.clone();
          caches.open(CACHE).then(function(c){ c.put(e.request, copy); });
        }
        return resp;
      }).catch(function(){ return cached; });
    })
  );
});
